DELIMITER $$
--
-- Procedimientos
--
CREATE PROCEDURE cambiartildes ()   BEGIN
update modulo set desmod=replace(desmod, 'Ã¡', 'á');
update modulo set desmod=replace(desmod, 'Ã©', 'é');
update modulo set desmod=replace(desmod, 'Ã­', 'í');
update modulo set desmod=replace(desmod, 'ó', 'Ã³');
update modulo set desmod=replace(desmod, 'Ãº', 'ú');
update modulo set desmod=replace(desmod, 'Ã', 'Á');
update modulo set desmod=replace(desmod, 'Ã‰', 'É');
update modulo set desmod=replace(desmod, 'Ã', 'Í');
update modulo set desmod=replace(desmod, 'Ã“', 'Ó');
update modulo set desmod=replace(desmod, 'Ãš', 'Ú');
update modulo set desmod=replace(desmod, 'Ã±', 'ñ');
update modulo set desmod=replace(desmod, 'Ã‘', 'Ñ');
END$$

DELIMITER ;

