--
-- Estructura de tabla para la tabla hojatra
--

CREATE TABLE hojatra (
  idnorad bigint(15) NOT NULL,
  codpro bigint(20) NOT NULL,
  idemp bigint(15) NOT NULL,
  codproesp int(11) NOT NULL,
  codslem varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  feclini date DEFAULT NULL,
  feclin date DEFAULT NULL,
  cupo int(11) DEFAULT NULL,
  jornada varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  idfic varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  convht varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  act tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Estado: 1=Activo, 2=Inactivo',
  codsena varchar(100) DEFAULT NULL,
  denominacion text DEFAULT NULL,
  ocupacion varchar(255) DEFAULT NULL,
  sector_econ varchar(255) DEFAULT NULL,
  gremio varchar(255) DEFAULT NULL,
  duracion int(11) DEFAULT NULL,
  tipo_edt varchar(255) DEFAULT NULL,
  objetivos text DEFAULT NULL,
  temas text DEFAULT NULL,
  poblacion text DEFAULT NULL,
  metodologia text DEFAULT NULL,
  resultados text DEFAULT NULL,
  perfil_orientador text DEFAULT NULL,
  observaciones text DEFAULT NULL,
  sector_programa varchar(255) DEFAULT NULL,
  tipo_evento varchar(255) DEFAULT NULL,
  subtipo_evento varchar(255) DEFAULT NULL,
  horario_propuesto text DEFAULT NULL,
  lugar_edt varchar(255) DEFAULT NULL,
  responsable varchar(255) DEFAULT NULL,
  nitemp varchar(100) DEFAULT NULL,
  modalidad_prog varchar(255) DEFAULT NULL,
  tipo_convenio varchar(255) DEFAULT NULL,
  paso_actual int(11) NOT NULL DEFAULT 1,
  estado varchar(60) NOT NULL DEFAULT 'En Revisión (Instructor)',
  devuelto_de int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

