--
-- Estructura de tabla para la tabla juicio
--

CREATE TABLE juicio (
  idjui int(11) NOT NULL COMMENT 'ID único del juicio',
  idusu int(11) NOT NULL COMMENT 'ID del usuario que realizó el juicio',
  idfic int(11) NOT NULL COMMENT 'ID de la ficha',
