--
-- Estructura de tabla para la tabla modulo
--

CREATE TABLE modulo (
  idmod int(11) NOT NULL,
  nommod varchar(200) NOT NULL,
  imgmod varchar(255) DEFAULT NULL,
  actmod tinyint(1) NOT NULL,
  idper int(11) DEFAULT NULL,
  ordmod tinyint(99) NOT NULL,
  mosmod tinyint(1) NOT NULL DEFAULT 1,
  desmod text NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Volcado de datos para la tabla modulo
--

INSERT INTO modulo (idmod, nommod, imgmod, actmod, idper, ordmod, mosmod, desmod) VALUES
(1, 'Votasena', 'fa-solid fa-users-rectangle', 1, 4, 1, 1, 'Permite participar en la elección de representantes del centro de formacion mediante un proceso ágil y sencillo. El modulo facilita la votacion, organiza las opciones disponibles, registra la participacion y mantiene el proceso ordenado. <br>Permite consultar las opciones disponibles y realizar la seleccion correspondiente de manera sencilla.Registra la participacion de los usuarios para mantener control sobre el proceso electoral.'),
(2, 'E/S', 'fa-solid fa-clipboard-check', 1, 8, 3, 1, 'Administra el registro de entradas y salidas de personas dentro del centro de formacion. Permite controlar los movimientos de ingreso y retiro, consultar registros y mantener informacion actualizada sobre quién se encuentra dentro. <br>Permite registrar los ingresos y salidas de las personas que acceden a las instalaciones.Facilita la consulta de los movimientos realizados y el control de las personas que permanecen dentro del centro.'),
(3, 'Configuración', 'fa-solid fa-gear', 1, 1, 98, 2, 'Permite administrar los parámetros generales del sistema y ajustar las opciones necesarias para el funcionamiento de los módulos. Facilita la gestión de valores, preferencias y configuraciones que requieren actualización según cada contexto. <br>Permite establecer y modificar los parámetros utilizados por los diferentes componentes de la plataforma.Centraliza las opciones de configuración para facilitar la administración y adaptación del sistema.'),
(4, 'Datos Personales', 'fa-solid fa-bullhorn', 2, 5, 99, 2, 'Permite consultar y actualizar la informacion personal de los usuarios del centro de formacion. Centraliza los datos registrados y facilita su mantenimiento para conservar informacion organizada, disponible y actualizada en la plataforma. <br>Permite visualizar y modificar los datos personales registrados de cada usuario.Facilita mantener la informacion actualizada para su utilizacion en los diferentes procesos del sistema.'),
(5, 'Deserciones y Llamados', 'fa-solid fa-bullhorn', 1, 1, 5, 1, 'Permite registrar, consultar y gestionar los casos de desercion y los llamados realizados durante el proceso de formacion. Facilita el seguimiento de cada situacion y ayuda a mantener un control organizado sobre las acciones realizadas. <br>Permite registrar los casos identificados y documentar los llamados o acciones realizados.Facilita el seguimiento de cada caso y la consulta de su informacion para mantener un historial organizado.'),
(6, 'Préstamos', 'fa-solid fa-laptop', 1, 1, 13, 1, 'Permite gestionar el préstamo y devolución de elementos, equipos o recursos disponibles en el centro de formación. Facilita el registro de solicitudes, responsables, fechas y estados, manteniendo control sobre los recursos entregados. <br>Permite registrar los elementos entregados y asociarlos con el usuario responsable del préstamo.Facilita controlar las fechas de entrega y devolución, así como consultar el estado de cada recurso.'),
(7, 'Administrativo', 'fa-solid fa-suitcase', 1, 1, 19, 1, 'Centraliza la gestion de los procesos administrativos del centro de formacion, facilitando el registro, consulta y seguimiento de informacion relacionada con recursos y usuarios. Permite organizar las actividades desde un mismo espacio. <br>Permite gestionar informacion y actividades relacionadas con la operacion administrativa del centro.Facilita la consulta y organizacion de los datos necesarios para apoyar los diferentes procesos administrativos.'),
(8, 'Complementarios', 'fa-solid fa-graduation-cap', 1, 25, 9, 2, 'Permite consultar y gestionar las actividades complementarias asociadas al proceso de formacion. Facilita el registro y seguimiento de estas actividades para apoyar el desarrollo integral de los aprendices y mantener su informacion al día. <br>Permite consultar las actividades complementarias disponibles y registrar la participacion correspondiente.Facilita el seguimiento de las actividades realizadas como parte del proceso de formacion integral.'),
(9, 'Usuarios', 'fa-solid fa-address-book', 1, 1, 11, 1, 'Permite administrar los usuarios de la plataforma, controlando su informacion, acceso y estado dentro del sistema. Facilita la creacion, consulta, actualizacion y gestion de los perfiles necesarios para operar los diferentes modulos. <br>Permite crear y consultar los usuarios registrados en la plataforma.Facilita actualizar la informacion, administrar los perfiles y controlar el estado de acceso de cada usuario.'),
(10, 'Mesa de Ayuda', 'fa-solid fa-life-ring', 1, 1, 15, 1, 'Permite registrar y gestionar solicitudes de mantenimiento y soporte técnico relacionadas con los equipos informáticos del centro. Facilita el seguimiento de cada caso, la atencion de requerimientos y el control de las actividades realizadas. <br>Permite registrar solicitudes de soporte técnico y mantenimiento realizadas por los usuarios.Facilita asignar, consultar y hacer seguimiento a los casos hasta su atencion y cierre correspondiente.'),
(12, 'Horarios y Agendas', 'fa-solid fa-calendar-days', 1, 21, 7, 1, 'Permite organizar los horarios de clases y consultar la agenda académica de forma sencilla. Facilita la visualizacion y gestion de actividades programadas, ayudando a mantener ordenadas las jornadas y compromisos del proceso de formacion. <br>Permite consultar las actividades académicas programadas según los horarios establecidos.Facilita organizar y visualizar compromisos, clases y demás actividades relacionadas con la formacion.'),
(13, 'Etapa productiva', 'fa-solid fa-file-circle-check', 1, 23, 17, 1, 'Permite gestionar y hacer seguimiento a la etapa productiva del proceso de formacion. Facilita el registro de informacion, consulta de avances y control de las actividades prácticas realizadas por los aprendices durante esta etapa. <br>Permite registrar y consultar la informacion relacionada con el desarrollo de la etapa productiva.Facilita realizar seguimiento a las actividades prácticas y consultar los avances registrados durante este proceso.'),
(14, 'Video TV', 'fa-solid fa-video', 1, 1, 23, 1, 'El modulo Video TV gestiona el contenido audiovisual que se presenta en pantallas externas y en otros espacios de la plataforma. Permite administrar videos, controlar su disponibilidad y organizar la reproduccion del contenido seleccionado. <br>¿Qué permite hacer este modulo?Crear, consultar, editar y eliminar (CRUD): Administra la informacion básica de cada video, incluyendo datos como título, descripcion y categorías, para mantener organizada la biblioteca audiovisual.Cargar nuevos videos: Permite subir archivos de video directamente al sistema desde el equipo del usuario de forma rápida y sencilla.Activar o desactivar contenido: Controla qué videos se encuentran disponibles para visualizacion y cuáles permanecen ocultos o inactivos sin necesidad de eliminarlos.Proyeccion en otros modulos: Permite conectar los videos seleccionados con pantallas, monitores, paneles informativos u otros espacios de la plataforma para reproducir el contenido automáticamente.En resumen: El modulo permite administrar el contenido audiovisual desde un solo lugar, controlar su disponibilidad y definir qué informacion se presenta en las diferentes pantallas del sistema.'),
(15, 'Solicitud EDT', 'fa-solid fa-file-signature', 1, 1, 21, 1, 'Gestiona las solicitudes de Eventos de Divulgacion Tecnologica, permitiendo registrar la solicitud, cargar archivos, solicitar el curso, gestionar su aprobacion por coordinacion y continuar el proceso con Administracion Educativa. <br><br><strong>¿Qué permite hacer este modulo?</strong><br><br><strong>Registrar solicitudes:</strong> Permite crear y gestionar las solicitudes relacionadas con Eventos de Divulgacion Tecnologica, recopilando la informacion necesaria para iniciar el proceso.<br><br><strong>Cargar archivos:</strong> Permite adjuntar y gestionar los documentos requeridos para soportar la solicitud y continuar con las diferentes etapas del proceso.<br><br><strong>Solicitar el curso:</strong> Facilita la gestion de la solicitud del curso o actividad de divulgacion tecnologica asociada al evento.<br><br><strong>Aprobacion por coordinacion:</strong> Permite que la coordinacion revise la informacion y gestione la aprobacion correspondiente antes de continuar con el proceso.<br><br><strong>Gestion por Administracion Educativa:</strong> Una vez aprobada la solicitud, permite que Administracion Educativa continúe con las actividades necesarias para gestionar y ejecutar el proceso.<br><br><strong>En resumen:</strong> EDP centraliza el proceso completo de los Eventos de Divulgacion Tecnologica, desde la solicitud y carga de documentos hasta la aprobacion y gestion final por parte de las áreas responsables.');

