CREATE TABLE pagina (
  idpag bigint(20) NOT NULL,
  nompag varchar(255) NOT NULL,
  rutpag varchar(255) NOT NULL,
  mospas tinyint(1) NOT NULL,
  ordpag int(11) NOT NULL,
