(1205, 'Certificado', 'views/votvcer.php', 1, 4, 'fa fa-solid fa-print', 1, 'El módulo Certificado Representante permite al aprendiz generar e imprimir el\r\ncertificado que valida su participación en la votación de representantes de aprendices\r\ndel SENA.<br>\r\nDesde este apartado el usuario puede visualizar sus datos personales y del centro de\r\nformación, así como descargar o imprimir el documento oficial del evento.\r\n', 2),
