(1208, 'Resultados', 'views/votvrvo.php', 1, 9, 'fa fa-solid fa-square-poll-vertical', 1, 'El módulo Resultados permite consultar los votos obtenidos por cada candidato en el\r\nproceso electoral de Representantes de Aprendices. <br>Desde este apartado, el usuario\r\npuede filtrar los datos por jornada y centro de formación, visualizar la lista completa de\r\ncandidatos junto con sus votos, e imprimir documentos como el acta general o el listado\r\nde votantes.', 2),
