(1311, 'Reporte Inasistencia', 'views/desrins.php', 1, 4, 'fa fa fa-regular fa-calendar-days', 5, 'El módulo Generar Inasistencia permite al administrador o instructor registrar y\r\ngestionar la asistencia de los aprendices pertenecientes a una ficha de formación. <br>\r\nDesde esta vista se pueden marcar aprendices como asistentes, inasistentes,\r\npendientes o con novedades, además de generar actas, registrar llamados de atención,\r\nagregar novedades o revisar el historial individual.\r\n', 2),
(1323, 'No votantes', 'views/votvnvot.php', 1, 7, 'fa fa fa-regular fa-calendar-days', 1, 'El módulo No Votantes permite visualizar de manera clara cuántos usuarios participaron\r\nen la votación y cuántos no lo hicieron. Además, muestra una tabla detallada con cada\r\nusuario, su perfil, datos personales y una indicación visual que muestra si votó o no.\r\nTambién incluye un gráfico estadístico para facilitar la interpretación de los resultados.', 2),
(1324, 'Datos Personales', 'views/datvdp.php', 1, 1, 'fa fa-solid fa-user-tie  ', 4, '', 2),
(1325, 'Registro E/S', 'views/esvres.php', 1, 1, 'fa fa-solid fa-arrows-rotate', 2, 'En este módulo permite registrar las entradas y salidas de usuarios, objetos y vehículos\r\nen la institución de acuerdo con su número de documento del usuario previamente\r\nregistrado en el sistema.', 2),
(1404, 'Minuta', 'views/esvmin.php', 1, 5, 'fa fa-solid fa-file-pen', 2, 'En este módulo de minuta podrá visualizar el historial completo de las entradas y\r\nsalidas registradas en cualquier periodo de fechas y de manera más detallada.', 2),
(1405, 'E/S', 'views/esvcanusu.php', 1, 1, 'fa fa-solid fa-clock', 2, 'En este módulo se visualizará las entradas y salidas de usuarios, objetos y vehículos en\r\nla institución.\r\n', 2),
(1406, 'Elementos', 'views/prevvele.php', 1, 2, 'fa fa-solid fa-boxes-stacked', 6, '', 2),
