(1503, 'Préstamo Elementos', 'views/prevprele.php', 1, 9, 'fa fa-solid fa-volleyball', 6, 'El módulo Préstamo de Elementos permite registrar, gestionar y controlar el préstamo\r\nde herramientas, dispositivos o materiales entregados a los usuarios dentro del sistema.\r\nDependiendo del rol del usuario, las opciones disponibles pueden variar.<br> Los usuarios\r\nque NO son administradores no pueden registrar préstamos ni marcar entregas.\r\n', 2),
