(1532, 'Prestamo Aula', 'views/prevpra.php', 1, 15, 'fa fa-solid fa-building-circle-check', 6, 'El módulo Préstamo de Aula permite gestionar en tiempo real la ocupación de aulas\r\ndentro de la institución, organizadas por piso, bloque y aula.<br> A través de esta interfaz,\r\nlos usuarios pueden ocupar o desocupar aulas, mientras que los administradores\r\npueden visualizar, liberar y registrar comentarios asociados a cada préstamo.<br>\r\nEste módulo facilita el control del uso de espacios físicos, evitando duplicidad de\r\nreservas y permitiendo una trazabilidad clara de quién ocupa cada aula.\r\n', 2),
(1533, 'Histórico Aulas', 'views/prevhaul.php', 1, 10, 'fa fa-solid fa-door-open', 6, 'El módulo Histórico de Aula permite consultar y generar reportes del uso histórico de las\r\naulas dentro del sistema. A través de diferentes filtros, el usuario puede identificar qué\r\ninstructor o usuario utilizó un aula específica, en qué fechas y bajo qué estado.', 2),
