(2110, 'Reporte gerencial de fichas por inscritos, matriculados', 'views/vrgfi.php', 2, 17, 'fa fa-solid fa-file-lines', 9, '', 2),
(2111, 'Documentos a pedir', 'views/vdpdr.php', 2, 6, 'fa fa-solid fa-file-import', 9, '', 2),
(2112, 'Generador de documentos', 'views/convcpr.php', 1, 4, 'fa fa-solid fa-file-circle-check', 3, '', 2),
(2113, 'Detalle de generador', 'views/convdcpr.php', 1, 5, 'fa fa-solid fa-file-circle-check', 3, '', 2),
(2114, 'Carga Masiva Aspirante', 'views/vcmausu.php', 2, 7, 'fa fa-solid fa-users-gear', 9, '', 2),
(2115, 'Trazabilidad Matricula', 'views/vtzmat.php', 2, 3, 'fa fa-solid fa-stairs', 9, '', 2),
(2116, 'Carga documentos', 'views/vcmdocmt.php', 2, 12, 'fa fa-solid fa-download', 9, '', 2),
(2117, 'Evaluación', 'views/horveval.php', 1, 5, 'fa fa-solid fa-user', 12, '', 2),
(2118, 'Carga Masiva Aspirante 2', 'views/vcmausu2.php', 2, 10, 'fa fa-solid fa-users-gear ', 9, '', 2),
(2201, 'Servicio Soporte', 'views/mesvser.php', 1, 1, 'fa fa-solid fa-hand-point-up', 10, 'Esta página permite a los <strong>técnicos y administradores</strong> de mesa de ayuda, crear un soporte de forma manual rellenando el formulario.<br> De esta manera   permitiendo crear un registro de un soporte. En conclusión, con esta herramienta, se agiliza el proceso de registro y se garantiza que toda la información necesaria se capture de manera precisa.', 2),
(2202, 'Detalle soporte', 'views/mesvdsop.php', 1, 2, 'fa fa-solid fa-handshake-angle', 10, 'Esta página ofrece al <strong>administrador de TIC</strong> del centro una vista general del desempeño de todo el equipo, esto incluye datos como cuantos usuarios han atendido cada uno de los técnicos, cuantos casos se han hecho y a que usuarios se han atendido y cuantos.<br> Permitiendo un monitoreo completo y consolidado del rendimiento del centro.', 2),
(2203, 'Reporte Est Personal', 'views/mesvestp.php', 1, 3, 'fa fa-solid fa-user', 10, 'Esta página muestra tu <strong>desempeño personal</strong>, incluyendo el número de casos que han resuelto, los que aún están en proceso y los que ya se han finalizado. En cuanto a los gráficos permite de visualizar al igual cuantos casos a atendido y a que usuarios de cada perfil en especifico se han atendido.', 2),
(2204, 'Seguimiento Soporte', 'views/mesvsspo.php', 2, 4, 'fa fa-solid fa-list-check', 10, 'Esta página permite dar <strong>seguimiento a las solicitudes de soporte</strong>. Para esto debe hacer clic en la lupa para abrir una ventana, completar los datos que se piden en el formulario y continuar con el proceso y/o finalizarlo.', 2),
(2301, 'Bitacora', 'views/', 2, 1, 'fa fa-solid fa-clipboard-list', 13, '', 2),
(2302, 'Solicitud Certificaciones', 'views/etavslcer.php', 1, 2, 'fa fa-solid fa-file-shield', 13, '', 2),
(2401, 'Paz y Salvos', 'views/admvpys.php', 1, 1, 'fa fa-solid fa-file-circle-check', 7, 'El módulo Paz y Salvos permite a los usuarios consultar, visualizar y descargar su paz y\r\nsalvo vigente y el historial de paz y salvos generados dentro del sistema. <br> Este\r\ndocumento certifica que el usuario no presenta obligaciones pendientes con la\r\ninstitución', 2),
(2402, 'Aulas Especiales', 'views/prevvprsp.php', 1, 1, 'fa fa-solid fa-file-lines', 6, NULL, 2),
(2403, 'Administracion Dep', 'views/admvadep.php', 1, 2, 'fa fas fa-building ', 7, 'El módulo Dependencias permite crear, editar y administrar las dependencias de la\r\norganización, así como asignar uno o varios líderes a cada dependencia. <br> Este módulo\r\nes clave para la correcta organización jerárquica y la gestión de responsabilidades\r\ndentro del sistema.', 2),
(2404, 'Gestión Instructores', 'views/etavgeins.php', 1, 6, 'fa fa-solid fa-user-tie ', 13, '', 2),
(2405, 'Evaluar Bitacoras', 'views/etavebit.php', 1, 7, 'fa fa-solid fa-file-circle-check ', 13, '', 2),
(2406, 'Aprobador PS', 'views/admvaps.php', 1, 3, 'fa fas fa-id-card ', 7, 'El módulo Aprobador Paz y Salvo permite a los líderes de dependencia revisar, aprobar\r\no rechazar los procesos de Paz y Salvo de los empleados que pertenecen a las\r\ndependencias bajo su cargo.\r\n', 2),
(2409, 'Coordinacion Etapa Productiva', 'views/etavcep.php', 1, 1, 'fa fa-solid fa-right-left', 13, '', 2),
(2410, 'Gestion de Solicitudes ', 'views/etavgssol.php', 1, 2, 'fa fa-solid fa-file-lines ', 13, '', 2),
(2411, 'Atención Casos', 'views/mesvsop.php', 1, 4, 'fa fa-solid fa-table', 10, 'En esta página, los técnicos pueden atender las <strong>solicitudes de soporte</strong> de los usuarios. Para ello, el técnico en turno debe hacer clic en el botón <i>(el de la persona con un más)</i> para asignarse el caso. De esta forma el caso quedara ligado a su perfil, como uno de los casos que este atendiendo', 2),
(2412, 'Enviar Solicitud Soporte', 'views/mesvesop.php', 1, 1, 'fa fa-solid fa-headset', 10, 'Esta página te permite <strong>registrar una solicitud de soporte</strong>. Para esto simplemente despliegue el formulario y llene los datos requeridos, posteriormente debe haberse creado el caso, lo único que hace falta es esperar a que un técnico mire su caso y empiece el seguimiento.', 2),
(2414, 'Juicios de Evaluaciòn', 'views/horvjuev.php', 1, 1517, 'fa fa-solid fa-file-lines ', 12, 'El módulo Prestado de Espacios Especializados permite a los usuarios solicitar, editar,\r\ncancelar y visualizar reservas de espacios como aulas, laboratorios o ambientes\r\nespeciales del centro, además, permite a los administradores aprobar o desaprobar\r\ndichas solicitudes y visualizar el historial de reservas de cada espacio.', 2),
(2415, 'Novedades', 'views/vnov.php', 1, 3, 'fa fa-solid fa-phone-volume', 5, 'El módulo Novedades permite a los aprendices consultar los llamados de atención que\r\nles han sido generados por parte de los instructores.<br>\r\nDesde esta interfaz, los aprendices pueden firmar los llamados pendientes, visualizar\r\nlos detalles del motivo, la fecha, el tipo de llamado y el nombre del instructor\r\nresponsable.<br>\r\nAdemás, se pueden imprimir los documentos oficiales de cada llamado directamente\r\ndesde el sistema.\r\n', 2),
(2416, 'Llamado de atencion', 'views/vrllam.php', 2, 4, 'fa fa-solid fa-phone-volume', 5, 'Llamado de atencion', 2),
(2417, 'Firma de certificaciones', 'views/vcertisub.php', 1, 4, ' fa fas fa-vote-yea ', 13, ' fa fas fa-vote-yea ', 2),
(2418, 'Videos TV', 'views/vvidgen.php', 1, 1, 'fa fa-solid fa-video', 14, 'Video TV es el centro de control del contenido audiovisual de la plataforma. Su función principal es gestionar los videos institucional o publicitarios que se muestran en las pantallas externas o en otros módulos del sistema.', 2),
(2419, 'Gestión Documentos Aspirante', 'views/convdocg.php', 1, 47, 'fa fa-solid fa-file-contract', 3, 'Permite buscar aspirantes por número de documento y gestionar la carga/consulta de documentos exigidos: certificados académicos, identificación, documentación complementaria y documentos para extranjeros.', 2),
(2447, 'Carton Electoral', 'views/votvctele.php', 2, 15, '', 1, '', 2),
