--
-- Estructura de tabla para la tabla patrocinio
--

CREATE TABLE patrocinio (
  idpat bigint(20) NOT NULL,
  idusu bigint(20) NOT NULL COMMENT 'Aprendiz patrocinado (usuario.idusu)',
  idemp bigint(15) NOT NULL COMMENT 'Empresa patrocinadora (empresa.idemp)',
  estpat tinyint(1) NOT NULL DEFAULT 1 COMMENT '1=Activo, 0/2=Cancelado, 3=Finalizado',
  usucre bigint(20) DEFAULT NULL COMMENT 'Usuario que registró el patrocinio',
  feccre datetime NOT NULL DEFAULT current_timestamp() COMMENT 'Fecha de inicio del patrocinio'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

